import type { ReactNode } from "react"
import { useIsMobile } from "@/hooks/use-mobile"
import { Popover, PopoverContent, PopoverTrigger } from "../ui/popover"
import { Button, buttonVariants } from "../ui/button"
import { ChevronLeft, Plus } from "lucide-react"
import { Link } from "react-router-dom"
import { cn } from "cn"

interface HeaderTemplateProps {
  title?: string
  subtitle?: string
  cta?: ReactNode[]
  backTo?: string
  classname?: string
}

export default function HeaderTemplate({
  title = "Page Title",
  subtitle = "Page Subtitle",
  cta,
  backTo,
  classname,
}: HeaderTemplateProps) {
  const isMobile = useIsMobile()
  const hasCta = Boolean(cta && cta.length > 0)

  document.title = `${title} | FrontAccEase`
  return (
    <header className={cn("space-y-6", classname)}>
      {backTo && (
        <Link
          to={backTo}
          className={cn(buttonVariants({ variant: "ghost", size: "xs" }))}
        >
          <ChevronLeft />
          Back
        </Link>
      )}
      <div className="flex items-center justify-between">
        <div className="space-y-1">
          <h1 className="text-lg font-bold tracking-tight capitalize sm:text-xl md:text-2xl lg:text-3xl">
            {title}
          </h1>
          <p className="text-base">{subtitle}</p>
        </div>
        {hasCta &&
          (!isMobile ? (
            <div className="flex items-center gap-2">
              {cta!.map((btn, index) => (
                <div key={index} className="flex items-center">
                  {btn}
                </div>
              ))}
            </div>
          ) : (
            <Popover>
              <PopoverTrigger
                render={
                  <Button
                    size="icon"
                    className="fixed right-10 bottom-10 z-50 h-12 w-12 rounded-full shadow-lg"
                    aria-label="Actions"
                  >
                    <Plus className="h-6 w-6" />
                  </Button>
                }
              />
              <PopoverContent className={"w-fit"} align="end">
                {cta!.map((btn, index) => (
                  <div key={index} className="">
                    {btn}
                  </div>
                ))}
              </PopoverContent>
            </Popover>
          ))}
      </div>
    </header>
  )
}

import { LogOut, Settings, SidebarIcon } from "lucide-react"
import {
  Sidebar,
  SidebarContent,
  SidebarFooter,
  SidebarGroup,
  SidebarHeader,
  SidebarMenu,
  SidebarMenuButton,
  SidebarMenuItem,
  useSidebar,
} from "../ui/sidebar"
import { Logo } from "./Logo"
import { Tooltip, TooltipContent, TooltipTrigger } from "../ui/tooltip"
import { NavLink, useNavigate } from "react-router-dom"
import { Avatar, AvatarFallback, AvatarImage } from "../ui/avatar"
import { useInvalidateKeys } from "@/services/tanstack/auth"
// import { Button } from "../ui/button"
import { useIsMobile } from "@/hooks/use-mobile"
import { Popover, PopoverContent, PopoverTrigger } from "../ui/popover"
import { ModeToggle } from "../modeToggle"
import ToolTipTemplate from "./TooltipButtonTemplate"
import { Button } from "../ui/button"

interface UserSidebarProps {
  links: { name: string; href: string; icon: any }[]
  name: string
}

export default function UserSidebar({ links, name }: UserSidebarProps) {
  const { open, setOpen, openMobile, setOpenMobile } = useSidebar()
  const invalidate = useInvalidateKeys()
  const isMobile = useIsMobile()

  async function handleLogout() {
    const nav = useNavigate()
    nav("/")
    invalidate(["user"])
  }

  return (
    <Sidebar side={isMobile ? "right" : "left"} collapsible="icon">
      <SidebarHeader className="overflow-hidden">
        <div className="flex items-center gap-2">
          <div className="group/logo flex h-8 w-8 items-center justify-center">
            <Logo
              size={32}
              className={!open ? "group-hover/logo:hidden" : ""}
            />

            {!open && (
              <Tooltip>
                <TooltipTrigger
                  render={(triggerProps) => (
                    <button
                      {...triggerProps}
                      type="button"
                      onClick={(e) => {
                        triggerProps.onClick?.(e)
                        setOpen(true)
                      }}
                      className="hidden rounded-md p-2 group-hover/logo:block hover:bg-muted"
                    >
                      <SidebarIcon size={16} />
                    </button>
                  )}
                />
                <TooltipContent>Open Sidebar</TooltipContent>
              </Tooltip>
            )}
          </div>

          <div className="flex h-full flex-1 shrink-0 flex-col justify-center text-lg font-bold">
            <span>FrontAccEase</span>
          </div>

          {open && !isMobile && (
            <ToolTipTemplate
              triggerTextIcon={<SidebarIcon size={16} />}
              content="Close sidebar"
              triggerVariant="ghost"
              onClick={() => {
                setOpen(false)
              }}
            />
            // <Tooltip>
            //   <TooltipTrigger
            //     render={(triggerProps) => (
            //       <button
            //         {...triggerProps}
            //         type="button"
            //         onClick={(e) => {
            //           triggerProps.onClick?.(e)
            //           setOpen(false)
            //         }}
            //         className="rounded-md p-2 group-hover/logo:block hover:bg-muted"
            //       >
            //         <SidebarIcon size={16} />
            //       </button>
            //     )}
            //   />
            //   <TooltipContent>Close Sidebar</TooltipContent>
            // </Tooltip>
          )}
        </div>
      </SidebarHeader>

      <SidebarContent>
        <SidebarGroup>
          <SidebarMenu>
            {links.map((link) => (
              <SidebarMenuItem
                key={link.href}
                onClick={() => openMobile && setOpenMobile(false)}
              >
                <NavLink to={link.href} className="w-full">
                  {({ isActive }) => (
                    <SidebarMenuButton
                      isActive={isActive}
                      tooltip={link.name}
                      className=""
                      render={(menuProps) => (
                        <span {...menuProps}>
                          <link.icon />
                          <span>{link.name}</span>
                        </span>
                      )}
                    />
                  )}
                </NavLink>
              </SidebarMenuItem>
            ))}
          </SidebarMenu>
        </SidebarGroup>
      </SidebarContent>

      <SidebarFooter
        className={`${
          open || openMobile ? "flex-row items-center" : "flex-col-reverse"
        } justify-between pb-4`}
      >
        <NavLink
          to="/"
          onClick={() => {
            if (openMobile) setOpenMobile(false)
          }}
          className="flex shrink-0 items-center gap-2 overflow-hidden rounded-md py-2"
        >
          <Avatar>
            <AvatarImage
              src="https://github.com/shadcn.png"
              alt="@shadcn"
              className="grayscale"
            />
            <AvatarFallback>CN</AvatarFallback>
          </Avatar>
          <p className="shrink-0 capitalize">{name}</p>
        </NavLink>

        <div className="flex">
          <Popover>
            {/* <PopoverTrigger
              render={
                <ToolTipTemplate
                  trigger={<Settings size={16} />}
                  triggerVariant="ghost"
                  content="Settings"
                />
              }
            /> */}
            <Tooltip>
              <TooltipTrigger
                render={
                  <PopoverTrigger
                    render={
                      <SidebarMenuButton>
                        <Settings />
                      </SidebarMenuButton>
                    }
                  />
                }
              />
              {/* <PopoverTrigger
                render={(popoverProps) => (
                  <TooltipTrigger
                    render={(tooltipProps) => (
                      <Button
                        {...tooltipProps}
                        {...popoverProps}
                        variant="ghost"
                        size="icon"
                        aria-label="Settings"
                      >
                        <Settings size={16} />
                      </Button>
                    )}
                  />
                )}
              /> */}
              <TooltipContent>Settings</TooltipContent>
            </Tooltip>

            <PopoverContent
              align="start"
              side="bottom"
              sideOffset={8}
              className="flex w-56 flex-col gap-1 rounded-2xl border border-border/60 bg-popover/95 p-2 shadow-xl backdrop-blur-md"
            >
              {/* Theme Row */}
              <div className="flex items-center justify-between rounded-xl px-2.5 py-1.5 transition-colors hover:bg-muted/50">
                <span className="text-sm font-medium text-foreground">
                  Theme
                </span>
                <ModeToggle variant="select" />
              </div>

              <div className="my-0.5 h-px bg-border/40" />

              {/* Log Out Row */}
              <Button
                variant={"ghost"}
                type="button"
                onClick={() => {
                  handleLogout()
                  if (openMobile) setOpenMobile(false)
                }}
                className={"justify-start"}
              >
                <LogOut className="size-4 shrink-0" />
                <span>Log out</span>
              </Button>
            </PopoverContent>
          </Popover>
        </div>
      </SidebarFooter>
    </Sidebar>
  )
}

import { useMemo } from "react"
import {
  Accordion,
  AccordionContent,
  AccordionItem,
  AccordionTrigger,
} from "../ui/accordion"
import { Badge } from "@/components/ui/badge"
import { Avatar, AvatarFallback, AvatarImage } from "@/components/ui/avatar"
import { classrooms, learners, quizSubmissions } from "@/const/data"
import type { QuizProps } from "@/const/materialsProps"
import { Users, User, Clock, FileText } from "lucide-react"

export type QuizSubmissionsCardTemplateProps = {
  quiz: QuizProps
}

export default function QuizSubmissionsCardTemplate({
  quiz,
}: QuizSubmissionsCardTemplateProps) {
  const totalPoints = quiz.totalPoints ?? 50
  const quizClassroomIds = quiz.classrooms ?? []

  const assignedClassrooms = useMemo(
    () =>
      quizClassroomIds
        .map((cId) => classrooms.find((c) => String(c.id) === String(cId)))
        .filter(Boolean),
    [quizClassroomIds]
  )

  const matchingSubmissions = useMemo(
    () => quizSubmissions.filter((s) => String(s.quizId) === String(quiz.id)),
    [quiz.id]
  )

  const targetClassrooms =
    assignedClassrooms.length > 0 ? assignedClassrooms : classrooms.slice(0, 1)

  const defaultExpandedIds = useMemo(
    () => targetClassrooms.map((c) => c?.id).filter(Boolean) as string[],
    [targetClassrooms]
  )

  if (!targetClassrooms.length) {
    return (
      <div className="flex flex-col items-center justify-center rounded-xl border border-dashed border-border py-14 text-center">
        <FileText className="mb-3 size-10 text-muted-foreground/60" />
        <p className="text-base font-semibold text-foreground">
          No classrooms assigned
        </p>
        <p className="text-sm text-muted-foreground">
          Submissions for assigned classrooms will appear here.
        </p>
      </div>
    )
  }

  return (
    <Accordion multiple defaultValue={defaultExpandedIds} className="space-y-3">
      {targetClassrooms.map((classroom) => {
        if (!classroom) return null

        const classroomLearners = classroom.learners
          .map((lId) => learners.find((l) => String(l.id) === String(lId)))
          .filter(Boolean)

        const submittedCount = classroomLearners.filter((l) =>
          matchingSubmissions.some((s) => String(s.learnerId) === String(l?.id))
        ).length

        const isCompleted =
          classroomLearners.length > 0 &&
          submittedCount >= classroomLearners.length

        return (
          <AccordionItem
            key={classroom.id}
            value={classroom.id}
            className="overflow-hidden rounded-xl border border-border bg-card shadow-sm transition-all hover:border-border/80"
          >
            <AccordionTrigger className="px-5 py-4 hover:no-underline">
              <div className="flex w-full items-center justify-between gap-4 pr-3 text-left">
                {/* Classroom Title & Code */}
                <div className="flex items-center gap-3.5">
                  <div className="flex size-9 shrink-0 items-center justify-center rounded-lg bg-primary/10 text-primary">
                    <Users className="size-4" />
                  </div>
                  <div>
                    <h3 className="text-sm font-semibold tracking-tight text-foreground md:text-base">
                      {classroom.name}
                    </h3>
                    <div className="mt-0.5 flex items-center gap-1.5 text-xs text-muted-foreground">
                      <span>Code: {classroom.classroomCode}</span>
                      <span>•</span>
                      <span>{classroomLearners.length} Enrolled Learners</span>
                    </div>
                  </div>
                </div>

                {/* Submission Progress Pill Badge */}
                <div className="flex items-center gap-2">
                  <Badge
                    variant={isCompleted ? "default" : "secondary"}
                    className="flex items-center gap-1.5 px-2.5 py-1 text-xs font-medium"
                  >
                    <Users className="size-3.5" />
                    <span>
                      {submittedCount} / {classroomLearners.length}
                    </span>
                  </Badge>
                </div>
              </div>
            </AccordionTrigger>

            <AccordionContent className="border-t border-border/50 bg-muted/20 px-5 pt-3 pb-4">
              {classroomLearners.length === 0 ? (
                <div className="flex items-center justify-center py-6 text-sm text-muted-foreground">
                  <Clock className="mr-2 size-4" />
                  <span>No enrolled learners found in this classroom.</span>
                </div>
              ) : (
                <div className="divide-y divide-border/40 rounded-lg border border-border/60 bg-background">
                  {classroomLearners.map((learner) => {
                    if (!learner) return null
                    const submission = matchingSubmissions.find(
                      (s) => String(s.learnerId) === String(learner.id)
                    )
                    const isSubmitted = !!submission
                    const score = submission?.score ?? 0
                    const ratio = score / totalPoints

                    let scoreBadgeClass =
                      "border-emerald-500/30 text-emerald-700 bg-emerald-50/50 dark:bg-emerald-950/30 dark:text-emerald-400"
                    if (ratio < 0.6) {
                      scoreBadgeClass =
                        "border-rose-500/30 text-rose-700 bg-rose-50/50 dark:bg-rose-950/30 dark:text-rose-400"
                    } else if (ratio < 0.8) {
                      scoreBadgeClass =
                        "border-amber-500/30 text-amber-700 bg-amber-50/50 dark:bg-amber-950/30 dark:text-amber-400"
                    }

                    const initials = learner.name
                      .split(" ")
                      .map((n) => n[0])
                      .slice(0, 2)
                      .join("")
                      .toUpperCase()

                    return (
                      <div
                        key={learner.id}
                        className="flex items-center justify-between px-4 py-3 text-xs transition-colors hover:bg-muted/40 sm:text-sm"
                      >
                        <div className="flex items-center gap-3">
                          <Avatar className="size-8 border border-border text-xs font-semibold sm:size-9">
                            <AvatarImage src={learner.img} />
                            <AvatarFallback>
                              {initials || <User className="size-3.5" />}
                            </AvatarFallback>
                          </Avatar>
                          <div>
                            <p className="font-semibold text-foreground">
                              {learner.name}
                            </p>
                            <p className="text-[11px] text-muted-foreground">
                              {isSubmitted
                                ? `Submitted: ${submission?.submittedAt || "Recently"}`
                                : "No submission yet"}
                            </p>
                          </div>
                        </div>

                        <div className="flex items-center gap-2">
                          {isSubmitted ? (
                            <Badge
                              variant="outline"
                              className={`px-2.5 py-1 text-xs font-semibold ${scoreBadgeClass}`}
                            >
                              {score} / {totalPoints}
                            </Badge>
                          ) : (
                            <Badge
                              variant="secondary"
                              className="px-2.5 py-1 text-xs font-medium"
                            >
                              Missing
                            </Badge>
                          )}
                        </div>
                      </div>
                    )
                  })}
                </div>
              )}
            </AccordionContent>
          </AccordionItem>
        )
      })}
    </Accordion>
  )
}

import * as React from "react"

type Theme = "dark" | "light" | "system"
type ResolvedTheme = "dark" | "light"

type ThemeProviderProps = {
  children: React.ReactNode
  defaultTheme?: Theme
  storageKey?: string
  disableTransitionOnChange?: boolean
}

type ThemeProviderState = {
  theme: Theme
  setTheme: (theme: Theme) => void
}

const COLOR_SCHEME_QUERY = "(prefers-color-scheme: dark)"
const THEME_VALUES: Theme[] = ["dark", "light", "system"]

const ThemeProviderContext = React.createContext<
  ThemeProviderState | undefined
>(undefined)

function isTheme(value: string | null): value is Theme {
  if (value === null) {
    return false
  }

  return THEME_VALUES.includes(value as Theme)
}

function getSystemTheme(): ResolvedTheme {
  if (window.matchMedia(COLOR_SCHEME_QUERY).matches) {
    return "dark"
  }

  return "light"
}

function disableTransitionsTemporarily() {
  const style = document.createElement("style")
  style.appendChild(
    document.createTextNode(
      "*,*::before,*::after{-webkit-transition:none!important;transition:none!important}"
    )
  )
  document.head.appendChild(style)

  return () => {
    window.getComputedStyle(document.body)
    requestAnimationFrame(() => {
      requestAnimationFrame(() => {
        style.remove()
      })
    })
  }
}

export function ThemeProvider({
  children,
  defaultTheme = "system",
  storageKey = "theme",
  disableTransitionOnChange = true,
  ...props
}: ThemeProviderProps) {
  const [theme, setThemeState] = React.useState<Theme>(() => {
    const storedTheme = localStorage.getItem(storageKey)
    if (isTheme(storedTheme)) {
      return storedTheme
    }

    return defaultTheme
  })

  const setTheme = React.useCallback(
    (nextTheme: Theme) => {
      localStorage.setItem(storageKey, nextTheme)
      setThemeState(nextTheme)
    },
    [storageKey]
  )

  const applyTheme = React.useCallback(
    (nextTheme: Theme) => {
      const root = document.documentElement
      const resolvedTheme =
        nextTheme === "system" ? getSystemTheme() : nextTheme
      const restoreTransitions = disableTransitionOnChange
        ? disableTransitionsTemporarily()
        : null

      root.classList.remove("light", "dark")
      root.classList.add(resolvedTheme)

      if (restoreTransitions) {
        restoreTransitions()
      }
    },
    [disableTransitionOnChange]
  )

  React.useEffect(() => {
    applyTheme(theme)

    if (theme !== "system") {
      return undefined
    }

    const mediaQuery = window.matchMedia(COLOR_SCHEME_QUERY)
    const handleChange = () => {
      applyTheme("system")
    }

    mediaQuery.addEventListener("change", handleChange)

    return () => {
      mediaQuery.removeEventListener("change", handleChange)
    }
  }, [theme, applyTheme])

  const value = React.useMemo(
    () => ({
      theme,
      setTheme,
    }),
    [theme, setTheme]
  )

  return (
    <ThemeProviderContext.Provider {...props} value={value}>
      {children}
    </ThemeProviderContext.Provider>
  )
}

export const useTheme = () => {
  const context = React.useContext(ThemeProviderContext)

  if (context === undefined) {
    throw new Error("useTheme must be used within a ThemeProvider")
  }

  return context
}

"use client"

import { useCallback, useEffect, useRef, useState } from "react"
import { EditorContent, EditorContext, useEditor } from "@tiptap/react"

// --- Tiptap Core Extensions ---
